def subtract(a, b):
    """
    Return points covered by some interval in a and by no interval in b,
    as a sorted list of disjoint [start, end) intervals.
    """
    # Filter out empty intervals and merge overlapping/touching intervals
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals (start >= end)
        valid = [interval for interval in intervals if interval[0] < interval[1]]

        if not valid:
            return []

        # Sort by start position
        valid.sort()

        # Merge overlapping or touching intervals
        merged = [valid[0]]
        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching - merge them
                merged[-1] = [merged[-1][0], max(merged[-1][1], end)]
            else:
                # Disjoint - add as new interval
                merged.append([start, end])

        return merged

    # Merge intervals in a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    if not b_merged:
        return a_merged

    # Subtract b from a
    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        # Remove each interval in b from current_ranges
        for b_start, b_end in b_merged:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # Check if b interval overlaps with current range
                if b_end <= c_start or b_start >= c_end:
                    # No overlap
                    new_ranges.append([c_start, c_end])
                else:
                    # There is overlap - keep the non-overlapping parts
                    if c_start < b_start:
                        new_ranges.append([c_start, b_start])
                    if b_end < c_end:
                        new_ranges.append([b_end, c_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort result
    result.sort()

    # Final merge in case we need to combine touching intervals
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1] = [merged_result[-1][0], max(merged_result[-1][1], end)]
        else:
            merged_result.append([start, end])

    return merged_result

